     * @suppress
     *
     * This constructor can be used to instantiate a fake object. Only used for tests. Any
     * attempt to actually use an object constructed this way will fail as there is no
     * connected Rust object.
     */
    @Suppress("UNUSED_PARAMETER")
    constructor(noHandle: NoHandle) {
        this.handle = 0
        this.cleanable = null
    }
    /**
     * One Endpoint per app. After `wipe_key` the app must construct a new `Core`.
     */
    constructor(`dataDir`: kotlin.String, `relay`: RelayConfig) :
        this(UniffiWithHandle, 
    uniffiRustCallWithError(CoreException) { _status ->
    UniffiLib.uniffi_ha_iroh_core_fn_constructor_core_new(
    
        
        FfiConverterString.lower(`dataDir`),
        FfiConverterTypeRelayConfig.lower(`relay`),_status)
}
    )

